from collections import deque

def serve(model, queue: deque, max_batch=32):
    running = []                                   # active sequences
    while queue or running:
        # admit new requests at every step while there is room
        while queue and len(running) < max_batch:
            req = queue.popleft()
            req.kv = model.prefill(req.prompt_ids)  # build KV cache for the prompt
            running.append(req)
        # one decoding step for all running sequences together
        next_tokens = model.decode_step([r.kv for r in running])
        still_running = []
        for req, tok in zip(running, next_tokens):
            req.output.append(tok)
            if tok == model.eos_id or len(req.output) >= req.max_tokens:
                req.finish()                        # leave the batch immediately
            else:
                still_running.append(req)
        running = still_running

