import torch
import torch.nn as nn

class HybridStack(nn.Module):
    """Interleave attention with recurrent/SSM-style blocks (e.g. 1:7)."""
    def __init__(self, d=256, n_layers=16, attn_every=8):
        super().__init__()
        layers = []
        for i in range(n_layers):
            if i % attn_every == attn_every // 2:
                layers.append(nn.TransformerEncoderLayer(d, nhead=8, batch_first=True))
            else:
                layers.append(nn.GRU(d, d, batch_first=True))   # stand-in for a Mamba layer
        self.layers = nn.ModuleList(layers)

    def forward(self, x):
        for layer in self.layers:
            if isinstance(layer, nn.GRU):
                x = x + layer(x)[0]          # residual around recurrent layer
            else:
                x = layer(x)                 # attention layer (has its own residuals)
        return x

y = HybridStack()(torch.randn(2, 128, 256))
